INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(30511, 'Mark 14:39', 'Mark', 14, 39, 'عیسی یوځل بیا لاړ او هماغه دعا یې وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_39.mp3', '', 1761754199, 1761754199),
(30512, 'Mark 14:40', 'Mark', 14, 40, 'کله چې هغه بېرته راغی، نو هغوی یې بیا په خوب ویده ولیدل، ځکه چې د هغوی سترګې له خوبه ډکې وې او په دې نه پوهېدل چې هغه ته څه ووایي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_40.mp3', '', 1761754199, 1761754199),
(30513, 'Mark 14:41', 'Mark', 14, 41, 'کله چې هغه د درېم ځل دپاره راغی، نو هغوی ته یې وویل: «تاسو لا ویده یئ او ارام کوئ؟ بس دی. هغه ساعت رارسېدلی دی چې د انسان زوی به ګناهکارانو ته په لاس ورکول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_41.mp3', '', 1761754199, 1761754199),
(30514, 'Mark 14:42', 'Mark', 14, 42, 'پاڅېږئ، راځئ چې ځو، هغه څوک چې غواړي زما سره خیانت وکړي، رارسېدلی دی.» د عیسی سره خیانت او د هغه نیول (متي ۲۶‏:‌۴۷‌‏-‌۵۶ او لوقا ۲۲‏:‌۴۷‌‏-‌۵۳ او یوحنا ۱۸‏:‌۳‌‏-‌۱۲)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_42.mp3', '', 1761754199, 1761754199),
(30515, 'Mark 14:43', 'Mark', 14, 43, 'عیسی لا خبرې کولې چې سمدلاسه یهودا چې د هغو دولسو شاګردانو څخه ؤ، د یوې ډلې خلکو سره چې تورې او کوتکونه ورسره وو، راورسېد. هغه د مشرانو کاهنانو، د شریعت د عالمانو او قومي مشرانو له خوا رالېږل شوی ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_43.mp3', '', 1761754199, 1761754199),
(30516, 'Mark 14:44', 'Mark', 14, 44, 'هغه خاین هغوی ته یوه نښه ورکړې وه او ورته ویلي یې وو: «څوک چې زه ښکل کړم، نو دا هماغه سړی دی. هغه ونیسئ او تر پوره څارنې لاندې یې بوځئ.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_44.mp3', '', 1761754199, 1761754199),
(30517, 'Mark 14:45', 'Mark', 14, 45, 'کله چې یهودا راورسېد، نو سمدلاسه عیسی ته ورغی او ورته ویې ویل: «استاذه!» او هغه یې ښکل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_45.mp3', '', 1761754199, 1761754199),
(30518, 'Mark 14:46', 'Mark', 14, 46, 'نو هغوی عیسی ته لاس ورواچاوه او هغه یې ونیوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_46.mp3', '', 1761754199, 1761754199),
(30519, 'Mark 14:47', 'Mark', 14, 47, 'بیا د هغو کسانو څخه چې هلته ولاړ وو یو یې توره راوویستله او د لوی کاهن په نوکر یې ګوزار وکړ او د هغه غوږ یې پرې کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_47.mp3', '', 1761754199, 1761754199),
(30520, 'Mark 14:48', 'Mark', 14, 48, 'بیا عیسی هغوی ته وویل: «ایا زه کوم داړه مار یم چې د تورو او کوتکونو سره زما د نیولو دپاره راغلي یئ؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_48.mp3', '', 1761754199, 1761754199),
(30521, 'Mark 14:49', 'Mark', 14, 49, 'زه هره ورځ ستاسو سره د خدای په کور کې وم او تعلیم به مې ورکاوه او تاسو زه ونه نیولم، خو د خدای کلام چې څه وایي هغه باید پوره شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_49.mp3', '', 1761754199, 1761754199),
(30522, 'Mark 14:50', 'Mark', 14, 50, 'بیا ټولو شاګردانو هغه پرېښود او وتښتېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_50.mp3', '', 1761754199, 1761754199),
(30523, 'Mark 14:51', 'Mark', 14, 51, 'په دې وخت کې یو ځوان چې د کتان یوه ټوټه یې د ځان څخه تاوه کړې وه، د عیسی پسې روان شو. هغوی هغه هم ونیوه،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_51.mp3', '', 1761754199, 1761754199),
(30524, 'Mark 14:52', 'Mark', 14, 52, 'خو هغه خپل کالي پرېښودل او لوڅ وتښتېده. د یهودیانو د شورا له خوا د عیسی محاکمه (متي ۲۶‏:‌۵۷‌‏-‌۶۸ او لوقا ۲۲‏:‌۵۴‌‏-‌۵۵،‌۶۳‌‏-‌۷۱ او یوحنا ۱۸‏:‌۱۳‌‏-‌۱۴،‌۱۹‌‏-‌۲۴)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_52.mp3', '', 1761754199, 1761754199),
(30525, 'Mark 14:53', 'Mark', 14, 53, 'هغوی عیسی لوی کاهن ته بوتو او هلته مشران کاهنان، قومي مشران او د شریعت عالمان سره راټول شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_53.mp3', '', 1761754199, 1761754199),
(30526, 'Mark 14:54', 'Mark', 14, 54, 'پطروس د لوی کاهن تر حوېلۍ پورې په هغه پسې شاته شاته روان ؤ او دننه ورغی او هلته د ساتونکو سره کښېناست او اور ته یې ځان تودولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_54.mp3', '', 1761754199, 1761754199),
(30527, 'Mark 14:55', 'Mark', 14, 55, 'مشرانو کاهنانو او ټولې شورا هڅه کوله چې د عیسی په خلاف کوم ثبوت پیدا کړي ترڅو هغه ووژل شي، خو هغوی کوم ثبوت پیدا نه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_55.mp3', '', 1761754199, 1761754199),
(30528, 'Mark 14:56', 'Mark', 14, 56, 'ډېرو خلکو د هغه په خلاف په دروغو شاهدي ورکړه، خو د هغوی شهادت د یو بل سره یوشان نه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_56.mp3', '', 1761754199, 1761754199),
(30529, 'Mark 14:57', 'Mark', 14, 57, 'بیا ځینې خلک پاڅېدل او د هغه په خلاف یې داسې د دروغو شاهدي ورکړه:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_57.mp3', '', 1761754199, 1761754199),
(30530, 'Mark 14:58', 'Mark', 14, 58, '«مونږ د هغه د خولې نه واورېدل چې ویې ویل: زه به دا د خدای کور چې د انسانانو په لاس جوړ شوی دی ورانوم او په درې ورځو کې به بل داسې کور جوړ کړم چې هغه به د انسانانو په لاسونو نه وي جوړ شوی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_58.mp3', '', 1761754199, 1761754199),
(30531, 'Mark 14:59', 'Mark', 14, 59, 'خو بیاهم د دې خلکو شاهدي سره یوشان نه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_59.mp3', '', 1761754199, 1761754199),
(30532, 'Mark 14:60', 'Mark', 14, 60, 'بیا لوی کاهن د هغوی ټولو په مخکې ودرېده او د عیسی څخه یې پوښتنه وکړه: «ایا ته دې تورونو ته چې هغوی یې درباندې لګوي، ځواب نه ورکوې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_60.mp3', '', 1761754199, 1761754199),
(30533, 'Mark 14:61', 'Mark', 14, 61, 'خو عیسی غلی پاتې شو او هېڅ ځواب یې ورنه کړ. یوځل بیا لوی کاهن ترې پوښتنه وکړه: «ایا ته مسیح، د مبارک خدای زوی یې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_61.mp3', '', 1761754199, 1761754199),
(30534, 'Mark 14:62', 'Mark', 14, 62, 'عیسی وویل: «هو، زه یم او تاسو به د انسان زوی ووینئ چې د مطلق قادر خدای ښي لاس ته ناست وي او د اسمان په ورېځو کې به راروان وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_62.mp3', '', 1761754199, 1761754199),
(30535, 'Mark 14:63', 'Mark', 14, 63, 'لوی کاهن خپل کالي وشکول او ویې ویل: «مونږ نورو شاهدانو ته څه اړتیا لرو؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_63.mp3', '', 1761754199, 1761754199),
(30536, 'Mark 14:64', 'Mark', 14, 64, 'تاسو دا کفر ویل واورېدل. ستاسو پرېکړه څه ده؟» نو هغوی ټولو هغه محکوم کړ او ویې ویل چې هغه د مرګ لایق دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_64.mp3', '', 1761754199, 1761754199),
(30537, 'Mark 14:65', 'Mark', 14, 65, 'ځینو خلکو ورباندې لاړې ورتو کړې او سترګې یې ورته وتړلې او په سوکانو یې واهه او ورته ویل یې: «اوس له غیبو ووایه چې ته چا ووهلې.» بیا ساتونکو هغه ونیوه او ویې واهه. پطروس له عیسی څخه انکار کوي (متي ۲۶‏:‌۶۹‌‏-‌۷۵ او لوقا ۲۲‏:‌۵۶‌‏-‌۶۲ او یوحنا ۱۸‏:‌۱۵‌‏-‌۱۸،‌۲۵‌‏-‌۲۷)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_65.mp3', '', 1761754199, 1761754199),
(30538, 'Mark 14:66', 'Mark', 14, 66, 'په دې وخت کې پطروس لاندې په حوېلۍ کې ؤ چې د لوی کاهن یوه وینځه راغله', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_66.mp3', '', 1761754199, 1761754199),
(30539, 'Mark 14:67', 'Mark', 14, 67, 'او ویې لیدل چې پطروس اور ته خپل ځان تودوي، نو هغې ورته په ځیر سره وکتل او ویې ویل: «ته هم د عیسی ناصري سره وې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_67.mp3', '', 1761754199, 1761754199),
(30540, 'Mark 14:68', 'Mark', 14, 68, 'خو هغه منکر شو او ویې ویل: «زه هغه نه پېژنم او نه پوهېږم چې ته څه وایې.» بیا هغه دباندې دالان ته ووت او په هماغه وخت کې چرګ اذان وکړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_68.mp3', '', 1761754199, 1761754199),
(30541, 'Mark 14:69', 'Mark', 14, 69, 'هغې وینځې پطروس هلته ولیده او په هغه ځای کې ولاړو خلکو ته یې بیا وویل: «دا هم د هغوی د ډلې څخه دی.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_69.mp3', '', 1761754199, 1761754199),
(30542, 'Mark 14:70', 'Mark', 14, 70, 'خو پطروس بیا منکر شو. لږه شېبه وروسته حاضرو خلکو یوځل بیا پطروس ته وویل: «بې له شکه چې ته د هغوی د ډلې څخه یې، ځکه چې ته هم جلیلي یې.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_70.mp3', '', 1761754199, 1761754199),
(30543, 'Mark 14:71', 'Mark', 14, 71, 'خو پطروس قسم وخوړ: «که زه دروغ وایم، نو په ما دې د خدای لعنت وي، تاسو چې د کوم سړي په هکله خبرې کوئ زه هغه نه پېژنم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_71.mp3', '', 1761754199, 1761754199),
(30544, 'Mark 14:72', 'Mark', 14, 72, 'او سمدلاسه د دوهم ځل دپاره چرګ اذان وکړ. او پطروس ته ور په یاد شول چې عیسی ورته ویلي وو: «مخکې له دې چې چرګ دوه ځلې اذان وکړي، نو ته به درې ځلې ووایې چې زه هغه نه پېژنم.» د هغه زړه مات شو او په ژړا شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/mark14_verse_72.mp3', '', 1761754199, 1761754199),
(30545, 'Revelation 17:1', 'Revelation', 17, 1, 'بیا د هغو اوو فرښتو څخه چې جامونه یې په لاس کې وو، یوه یې ماته راغله او راته ویې ویل: «راشه، چې زه درته هغه مشهوره بدلمنه ښځه چې ډېرو سیندونو ته نژدې ناسته ده او سزا به ورته ورکول کیږي، دروښایم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_1.mp3', '', 1761754199, 1761754199),
(30546, 'Revelation 17:2', 'Revelation', 17, 2, 'د ځمکې پاچاهانو د هغې سره زنا کړې ده او د نړۍ خلک د هغې د زناکارۍ د شرابو په څښلو نشه شوي دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_2.mp3', '', 1761754199, 1761754199),
(30547, 'Revelation 17:3', 'Revelation', 17, 3, 'روح القدس زه تر خپلې اغېزې لاندې راوستلم او هغې فرښتې زه دښتې ته بوتلم. هلته ما یوه ښځه ولیدله چې په یو ځناور باندې چې سور رنګ یې ؤ، سپره وه. هغه ځناور اووه سرونه او لس ښکرونه لرل او په ټول بدن باندې یې کفري نومونه لیکل شوي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_3.mp3', '', 1761754199, 1761754199),
(30548, 'Revelation 17:4', 'Revelation', 17, 4, 'هغې ښځې بانجاني او سره کالي اغوستي وو او په سرو زرو، زېوراتو او مرغلرو باندې سینګار شوې وه. د هغې په لاس کې د سرو زرو پیاله وه چې د کرکې وړ کارونو او د هغې د زناکارۍ د ناپاکۍ څخه ډکه وه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_4.mp3', '', 1761754199, 1761754199),
(30549, 'Revelation 17:5', 'Revelation', 17, 5, 'د هغې په تندي باندې د پټ راز نه ډک یو نوم لیکل شوی ؤ: «لوی بابل، د ټولو بدلمنو او د ځمکې په مخ د ټولو د کرکې وړ کارونو مور.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_5.mp3', '', 1761754199, 1761754199),
(30550, 'Revelation 17:6', 'Revelation', 17, 6, 'ما ولیدل چې هغه ښځه د خدای د خلکو په وینه او د عیسی د شهیدانو په وینه نشه وه. کله چې ما هغه ولیدله نو ډېر حیران شوم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_6.mp3', '', 1761754199, 1761754199),
(30551, 'Revelation 17:7', 'Revelation', 17, 7, 'خو هغې فرښتې راته وویل: «ته ولې دومره حیران شوې؟ زه به تاته د هغې ښځې او د هغه ځناور چې اووه سرونه او لس ښکرونه لري او هغه ښځه ورباندې سپره ده، پټ راز ښکاره کړم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_7.mp3', '', 1761754199, 1761754199),
(30552, 'Revelation 17:8', 'Revelation', 17, 8, 'هغه ځناور چې تا ولیده، یو وخت ؤ خو اوس نشته او هغه به د ځمکې د تل څخه راپورته شي او هلاک به شي. هغه خلک چې د ځمکې په مخ ژوند کوي او نومونه یې د نړۍ د پیدایښت نه مخکې د ژوندون په کتاب کې نه وي لیکل شوي، نو هغوی به د دې ځناور په لیدلو سره حیران شي، ځکه چې هغه یو وخت ؤ او اوس نشته، خو بیاهم هغه به بیا راښکاره شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_8.mp3', '', 1761754199, 1761754199),
(30553, 'Revelation 17:9', 'Revelation', 17, 9, 'په دې شیانو باندې د پوهېدلو دپاره حکمت په کار دی. دا اووه سرونه د هغو اوو غونډیو استازیتوب کوي چې هغه ښځه ورباندې کښېني. هغوی هم د اوو پاچاهانو په معنی دي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_9.mp3', '', 1761754199, 1761754199),
(30554, 'Revelation 17:10', 'Revelation', 17, 10, 'چې پنځه یې د پاچاهۍ څخه لېرې شوي دي او یو یې اوس هم پاچاهي کوي او اووم یې لا تر‌اوسه نه دی راغلی او کله چې راشي، نو هغه باید د لږ وخت دپاره وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_10.mp3', '', 1761754199, 1761754199),
(30555, 'Revelation 17:11', 'Revelation', 17, 11, 'هغه ځناور چې یو وخت ژوندی ؤ خو اوس ژوندی نه دی، هغه اتم پاچا دی او د هغو اوو تنو څخه دی او هغه به هلاک شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_11.mp3', '', 1761754199, 1761754199),
(30556, 'Revelation 17:12', 'Revelation', 17, 12, 'هغه لس ښکرونه چې تا ولیدل، دا هغه لس پاچاهان دي چې تر‌اوسه لا پاچاهۍ ته نه دي رسېدلي، خو هغوی ته به د ځناور سره په پاچاهۍ کې د یو ساعت دپاره اختیار ورکړل شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_12.mp3', '', 1761754199, 1761754199),
(30557, 'Revelation 17:13', 'Revelation', 17, 13, 'ځکه چې د هغوی ټولو مقصد یو دی، چې خپل قدرت او اختیار به هغه ځناور ته ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_13.mp3', '', 1761754199, 1761754199),
(30558, 'Revelation 17:14', 'Revelation', 17, 14, 'هغوی به د وري سره جنګ وکړي، خو وری به په هغوی باندې بریالی شي، ځکه چې هغه د څښتنانو څښتن او د پاچاهانو پاچا دی او کوم کسان چې په دې بریالیتوب کې ورسره دي، د هغه بلل شوي، غوره شوي، او وفادار پیروان دي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_14.mp3', '', 1761754199, 1761754199),
(30559, 'Revelation 17:15', 'Revelation', 17, 15, 'بیا هغې فرښتې ماته وویل: «تا چې کومې اوبه ولیدلې چې هغه بدلمنه ښځه ورباندې ناسته وه، هغه قومونه، ولسونه، نژادونه او ژبې دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_15.mp3', '', 1761754199, 1761754199),
(30560, 'Revelation 17:16', 'Revelation', 17, 16, 'هغه لس ښکرونه چې تا ولیدل او هغه ځناور به د هغې بدلمنې څخه کرکه وکړي. هغوی به د هغې نه هرڅه واخلي او هغه به لوڅه پرېږدي. هغوی به د هغې د بدن غوښه وخوري او هغه به په اور کې وسوځوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_16.mp3', '', 1761754199, 1761754199),
(30561, 'Revelation 17:17', 'Revelation', 17, 17, 'ځکه چې خدای د هغوی په زړونو کې دا غوښتنه او اراده پیدا کړې وه چې په یو زړه د خدای د مقصد د پوره کولو دپاره هغه ځناور ته د خپلې پاچاهۍ واک او اختیار ورکړي، ترڅو هغه څه چې خدای په خپل کلام کې ویلي دي هغه رښتیا شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_17.mp3', '', 1761754199, 1761754199),
(30562, 'Revelation 17:18', 'Revelation', 17, 18, 'هغه ښځه چې تاسو ولیدله، دا هماغه لوی ښار دی چې د نړۍ په پاچاهانو حکومت کوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation17_verse_18.mp3', '', 1761754199, 1761754199),
(30563, 'John 3:1', 'John', 3, 1, 'په فریسیانو کې یو سړی ؤ چې نیکودیموس نومېده او د یهودیانو د مشرانو څخه ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_1.mp3', '', 1761754199, 1761754199),
(30564, 'John 3:2', 'John', 3, 2, 'یوه شپه هغه عیسی ته راغی او ورته ویې ویل: «استاذه، مونږ پوهېږو چې ته یو ښوونکی یې چې د خدای له خوا رالېږل شوی یې. کومې نښې چې ته یې ښایې هغه هېڅوک نه شي ښودلی ترڅو پورې چې خدای ورسره مل نه وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_2.mp3', '', 1761754199, 1761754199),
(30565, 'John 3:3', 'John', 3, 3, 'عیسی په ځواب کې وویل: «په یقین سره زه تاته دا وایم چې ترڅو پورې یو سړی بیا نوی پیدا نه شي هغه د خدای پاچاهي لیدلی نه شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_3.mp3', '', 1761754199, 1761754199),
(30566, 'John 3:4', 'John', 3, 4, 'نیکودیموس پوښتنه وکړه: «دا څنګه کېدای شي چې یو زوړ سړی بیا نوی پیدا شي؟ بې له شکه چې هغه نه شي کولای چې بېرته د مور ګېډې ته ورننوځي او د دوهم ځل دپاره بیا پیدا شي!»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_4.mp3', '', 1761754199, 1761754199),
(30567, 'John 3:5', 'John', 3, 5, 'عیسی ځواب ورکړ: «په یقین سره زه تاته دا وایم چې یو سړی به تر هغې پورې د خدای پاچاهۍ ته وردننه نه شي، ترڅو چې هغه په طبیعی ډول او روح القدس سره پیدا نه شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_5.mp3', '', 1761754199, 1761754199),
(30568, 'John 3:6', 'John', 3, 6, 'د انسان نه چې پیدا کیږي هغه جسم دی او د روح القدس نه چې پیدا کیږي هغه روح دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_6.mp3', '', 1761754199, 1761754199),
(30569, 'John 3:7', 'John', 3, 7, 'کله چې زه تاسو ته وایم چې تاسو ټول باید د دوهم ځل دپاره وزېږئ، نو په دې باندې مه حیرانېږئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_7.mp3', '', 1761754199, 1761754199),
