(30586, 'John 3:24', 'John', 3, 24, '(ځکه چې دا هغه وخت ؤ چې یحیی لا په زندان کې نه ؤ اچول شوی.)', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_24.mp3', '', 1761754199, 1761754199),
