(30596, 'John 3:34', 'John', 3, 34, 'ځکه څوک چې د خدای له خوا رالېږل شوی وي هغه د هغه پیغام په هکله خبرې کوي چې د خدای له خوا راځي، ځکه چې خدای ورته د اندازې نه زیات خپل روح ورکوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_34.mp3', '', 1761754199, 1761754199),
(30597, 'John 3:35', 'John', 3, 35, 'پلار د خپل زوی سره مینه کوي او د ټولو شیانو واک یې ورته ورکړی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_35.mp3', '', 1761754199, 1761754199),
(30598, 'John 3:36', 'John', 3, 36, 'څوک چې په زوی باندې ایمان راوړي نو هغه تلپاتې ژوندون لري، خو څوک چې د زوی نه اطاعت ونه کړي نو هغه به تلپاتې ژوندون ونه ویني، بلکې د خدای غضب به تل ورباندې وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john3_verse_36.mp3', '', 1761754199, 1761754199),
(30599, 'Revelation 20:1', 'Revelation', 20, 1, 'بیا ما یوه فرښته ولیدله چې د اسمان نه راښکته کېدله چې د ځمکې د تل کیلي او یو لوی زنځیر ورسره وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_1.mp3', '', 1761754199, 1761754199),
(30600, 'Revelation 20:2', 'Revelation', 20, 2, 'هغې ښامار یعنې هغه زوړ او پخوانی مار چې هماغه ابلیس یا شیطان دی، ونیوه او تر زرو کالو پورې یې په زنځیر وتاړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_2.mp3', '', 1761754199, 1761754199),
(30601, 'Revelation 20:3', 'Revelation', 20, 3, 'فرښتې هغه د ځمکې تل ته وغورځاوه، دروازه یې ورپسې وتړله او مهر یې ورباندې ولګاوه، ترڅو زر کاله پوره شوي نه وي، هغه نور ونه شي کولای چې قومونه وغولوي. له هغې وروسته باید د لږ وخت دپاره ازاد کړای شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_3.mp3', '', 1761754199, 1761754199),
(30602, 'Revelation 20:4', 'Revelation', 20, 4, 'بیا مې تختونه ولیدل چې هغه خلک پرې ناست وو چې د قضاوت کولو واک او اختیار ورته ورکړل شوی ؤ او د هغو کسانو روحونه مې ولیدل چې سرونه یې د عیسی په هکله د شاهدۍ ورکولو او د خدای د کلام په خاطر پرې کړل شوي وو. دا هغه خلک وو چې هغه ځناور او د هغه مجسمې ته یې سجده نه وه کړې او د هغوی تندي او لاسونو د هغو نښه نه درلودله. هغوی ټول بېرته راژوندي شول او د مسیح سره یې تر زرو کالو پورې پاچاهي وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_4.mp3', '', 1761754199, 1761754199),
(30603, 'Revelation 20:5', 'Revelation', 20, 5, 'خو هغه نور خلک چې مړه شوي وو، تر هغې پورې ژوندي نه شول ترڅو زر کاله پوره شوي نه وو. دا د مړو نه لومړنی بیا راژوندي کېدل دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_5.mp3', '', 1761754199, 1761754199),
(30604, 'Revelation 20:6', 'Revelation', 20, 6, 'بختور او سپېڅلی شوی هغه څوک دی چې په دې لومړني بیا راژوندي کېدلو کې شریک دی. ځکه چې په داسې خلکو د دوهم مرګ زور نه رسیږي، بلکې هغوی به د خدای او مسیح کاهنان وي او د هغه سره به تر زرو کالو پورې پاچاهي کوي. د شیطان ماتې', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_6.mp3', '', 1761754199, 1761754199),
(30605, 'Revelation 20:7', 'Revelation', 20, 7, 'کله چې زر کاله پوره شي، نو شیطان به د زندان څخه راخلاص شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_7.mp3', '', 1761754199, 1761754199),
(30606, 'Revelation 20:8', 'Revelation', 20, 8, 'هغه به راووځي او د نړۍ د څلورو کنجونو قومونه چې جوج او ماجوج بلل کیږي، وغولوي او هغوی چې د بحر د شګو په شان بې‌شمېره دي، د جنګ دپاره سره راټول کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_8.mp3', '', 1761754199, 1761754199),
(30607, 'Revelation 20:9', 'Revelation', 20, 9, 'هغوی په ټوله نړۍ کې خواره شول او د خدای د خلکو کمپ او ګران ښار یعنې اورشلیم یې کلابند کړ، خو د اسمان نه ورباندې اور نازل شو او هغوی یې تباه کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_9.mp3', '', 1761754199, 1761754199),
(30608, 'Revelation 20:10', 'Revelation', 20, 10, 'بیا شیطان چې هغوی یې غولولي وو، د اور او ګوګړو بحیرې ته وغورځول شو، یعنې هغه ځای ته چې هغه ځناور او جعلي پیغمبر هم په کې غورځول شوي وو. هغوی به هلته شپه او ورځ د تل دپاره عذاب ویني. وروستنی قضاوت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_10.mp3', '', 1761754199, 1761754199),
(30609, 'Revelation 20:11', 'Revelation', 20, 11, 'بیا مې یو لوی سپین تخت ولیده چې یو کس ورباندې ناست ؤ. ځمکه او اسمان د هغه د مخې نه وتښتېدل او نور ونه لیدل شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_11.mp3', '', 1761754199, 1761754199),
(30610, 'Revelation 20:12', 'Revelation', 20, 12, 'بیا ما مړي ولیدل چې د تخت په مخکې ولاړ وو، که هغه پیاوړي او که عادي خلک وو. هغه وخت کتابونه پرانیستل شول. وروسته د دې کتابونو څخه بیا بل کتاب پرانیستل شو، یعنې د ژوندون کتاب. د مړو په هکله لکه څنګه چې په کتابونو کې لیکل شوي وو او د هغوی د عملونو له مخې قضاوت وشو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation20_verse_12.mp3', '', 1761754199, 1761754199);